// Package main implements a multi-replica multi-version register whose
// conflict detection is based on vector clocks.
//
// A vector clock (type Clock) maps a replica id to the number of events
// generated by that replica known at a given point in history. It partially
// orders events:
//
//   - clock a  <= clock b  when every entry of a is <= the entry of b.
//   - a == b means the same history.
//   - a <  b means the event carrying a happened-before the event carrying b
//     (a causal overwrite is allowed to replace it).
//   - incomparable clocks denote concurrent events: neither happened-before
//     the other, so both versions must be kept as siblings.
package main

// Clock is a vector clock: replica id -> event counter.
// A nil Clock is valid and acts as the all-zero clock.
type Clock map[string]int64

// CompareClocks returns the partial-order relation between two vector clocks.
func CompareClocks(a, b Clock) ClockOrder {
	aLess := false // exists key: a[k] < b[k]
	bLess := false // exists key: b[k] < a[k]
	seen := make(map[string]struct{}, len(a)+len(b))
	for k := range a {
		seen[k] = struct{}{}
	}
	for k := range b {
		seen[k] = struct{}{}
	}
	for k := range seen {
		av, bv := a[k], b[k]
		switch {
		case av < bv:
			aLess = true
		case bv < av:
			bLess = true
		}
	}
	switch {
	case !aLess && !bLess:
		return ClockEqual
	case aLess && !bLess:
		return ClockBefore // a happened-before b
	case bLess && !aLess:
		return ClockAfter // b happened-before a
	default:
		return ClockConcurrent
	}
}

// ClockJoin returns the component-wise maximum of clocks: the vector clock
// that knows about every event either input clock knew about.
func ClockJoin(clocks ...Clock) Clock {
	out := Clock{}
	for _, c := range clocks {
		for k, v := range c {
			if v > out[k] {
				out[k] = v
			}
		}
	}
	return out
}

// Clone returns an independent copy of the clock (nil stays nil).
func (c Clock) Clone() Clock {
	if c == nil {
		return nil
	}
	out := make(Clock, len(c))
	for k, v := range c {
		out[k] = v
	}
	return out
}
